from google.cloud import firestore
import os


def get_firestore_client():
    project_id = os.environ.get("FIRESTORE_PROJECT_ID")
    if not project_id:
        raise ValueError("FIRESTORE_PROJECT_ID environment variable not set.")
    return firestore.Client(project=project_id)

from database_client import get_firestore_client
from database_models import Document


def fetch_document(document_id: str) -> Document | None:
    client = get_firestore_client()
    doc_ref = client.collection(r"documents").document(document_id)
    doc = doc_ref.get()
    if doc.exists:
        return Document(id=doc.id, document=doc.to_dict())
    return None

from database_client import get_firestore_client
from database_models import ConditionalUpdatePayload
from google.cloud.firestore import Transaction


def conditional_update(payload: ConditionalUpdatePayload) -> bool:
    client = get_firestore_client()
    transaction = client.transaction()

    @firestore.transactional
    def update_in_transaction(transaction, doc_ref, updates, condition_field, condition_value):
        snapshot = doc_ref.get(transaction=transaction)
        if not snapshot.exists:
            raise ValueError("Document does not exist.")

        current_data = snapshot.to_dict()
        if current_data.get(condition_field) == condition_value:
            transaction.update(doc_ref, updates)
            return True
        else:
            return False

    doc_ref = client.collection(r"documents").document(payload.id)
    try:
        return update_in_transaction(transaction, doc_ref, payload.updates, payload.condition_field, payload.condition_value)
    except ValueError:
        return False

import anthropic
import os


def record_summary(document_content: str) -> str:
    client = anthropic.Anthropic(api_key=os.environ.get("ANTHROPIC_API_KEY"))
    response = client.messages.create(
        model="claude-3-opus-20240229",
        max_tokens=100,
        messages=[
            {"role": "user", "content": f"Summarize the following document content: {document_content}"}
        ],
    )
    return response.content[0].text

from google.cloud import translate
import os


def record_translate(text_content: str, target_language: str) -> str:
    client = translate.TranslationServiceClient()
    project_id = os.environ.get("GOOGLE_CLOUD_PROJECT_ID")
    if not project_id:
        raise ValueError("GOOGLE_CLOUD_PROJECT_ID environment variable not set.")
    parent = f"projects/{project_id}/locations/global"

    response = client.translate_text(
        request={
            "parent": parent,
            "contents": [text_content],
            "target_language_code": target_language,
        }
    )

    return response.translations[0].translated_text
